<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_login();verify_csrf();$pdo=staff_db();$staff=current_staff();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("UPDATE notifications SET is_read=1,read_at=NOW() WHERE staff_id=?")->execute([$staff['id']]);staff_redirect('staff/pages/notifications.php');}$s=$pdo->prepare("SELECT * FROM notifications WHERE staff_id=? ORDER BY created_at DESC");$s->execute([$staff['id']]);$rows=$s->fetchAll();$pageTitle='Notifications';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Inbox</p><h1>Notifications</h1></div><form method="post"><?= csrf_field() ?><button class="btn">Mark all read</button></form></div><section class="staff-panel"><div class="list"><?php foreach($rows as $r):?><div class="list-row <?= !$r['is_read']?'unread':'' ?>"><div><b><?= h($r['title']) ?></b><small><?= h($r['message']) ?> · <?= h(date('j M Y, g:i A',strtotime($r['created_at']))) ?></small></div></div><?php endforeach;?></div></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
